namespace ghidra.app.util.viewer.field;








using docking.widgets.checkbox;
using docking.widgets.combobox;
using docking.widgets.label;
using docking.widgets.textfield;
using docking.widgets.textfield.integer;
using ghidra.framework.options;
using ghidra.util;
using ghidra.util.layout;

public class AddressFieldOptionsPropertyEditor : PropertyEditorSupport, CustomOptionsEditor {

	// names
	private static readonly string SHOW_BLOCK_NAME_LABEL = "Show Block Name";
	private static readonly string ADDRESS_DIGITS_LABEL = "Minimum Number of Address digits";
	private static readonly string PADDING_LABEL = "Fully Pad With Leading Zeros";
	private static readonly string JUSTIFICATION_LABEL = "Justification";
	private static readonly string UPPER_CASE_LABEL = "Display in Upper Case";

	private static readonly string[] NAMES = new string[] { SHOW_BLOCK_NAME_LABEL, ADDRESS_DIGITS_LABEL, PADDING_LABEL, JUSTIFICATION_LABEL,
			UPPER_CASE_LABEL };

	// help tooltips
	private static readonly string ADDRESS_PADDING_TOOLTIP = HTMLUtilities.toWrappedHTML(
		"Pads Addresses with leading zeros to the full size of the largest possible address.", 75);
	private static readonly string MIN_HEX_DIGITS_TOOLTIP = HTMLUtilities.toWrappedHTML(
		"Specifies the minimum number of hex digits to display the address (The " +
			"minimum is actually the smaller of this number and the number of digits in " +
			"largest possible address in that address space.)",
		75);
	private static readonly string SHOW_BLOCKNAME_TOOLTIP = HTMLUtilities.toWrappedHTML(
		"Prepends the Memory Block name to address in the address field.", 75);
	private static readonly string RIGHT_JUSTIFY_TOOLTIP = HTMLUtilities.toWrappedHTML(
		"Specifies the justification for address text in the address field. The address " +
			"text will clip on the opposite side of the justification.",
		75);
	private static readonly string UPPER_CASE_TOOLTIP = HTMLUtilities.toWrappedHTML(
		"Displays the hex digits of addresses in upper case in the address field.", 75);

	private static readonly string[] DESCRIPTIONS = new string[] { ADDRESS_PADDING_TOOLTIP, MIN_HEX_DIGITS_TOOLTIP,
		SHOW_BLOCKNAME_TOOLTIP, RIGHT_JUSTIFY_TOOLTIP, UPPER_CASE_TOOLTIP };

	private AddressFieldOptionsWrappedOption addressFieldOptionsWrappedOption;

	private Component editorComponent;
	private GCheckBox padCheckBox;
	private IntegerTextField minDigitsField;
	private GCheckBox showBlocknameCheckbox;
	private GhidraComboBox<string> justificationCombobox;
	private GCheckBox upperCaseCheckbox;

	public AddressFieldOptionsPropertyEditor() {
		editorComponent = buildEditor();
	}

	private Component buildEditor() {
		// we want to have a panel with our options so that we may group them together
		JPanel panel = new JPanel(new PairLayout(6, 10));

		GDLabel label = new GDLabel(SHOW_BLOCK_NAME_LABEL, SwingConstants.RIGHT);
		label.setToolTipText(SHOW_BLOCKNAME_TOOLTIP);
		panel.add(label);
		showBlocknameCheckbox = new GCheckBox();
		showBlocknameCheckbox.setToolTipText(SHOW_BLOCKNAME_TOOLTIP);
		panel.add(showBlocknameCheckbox);

		// the namespace checkbox will disable the text field options when it is not used
		label = new GDLabel(PADDING_LABEL, SwingConstants.RIGHT);
		label.setToolTipText(ADDRESS_PADDING_TOOLTIP);
		panel.add(label);
		padCheckBox = new GCheckBox();
		panel.add(padCheckBox);
		padCheckBox.setSelected(false);
		padCheckBox.setToolTipText(ADDRESS_PADDING_TOOLTIP);
		label = new GDLabel(ADDRESS_DIGITS_LABEL, SwingConstants.RIGHT);
		label.setToolTipText(MIN_HEX_DIGITS_TOOLTIP);
		panel.add(label);

		minDigitsField = new IntegerTextField(2);
		minDigitsField.setMinValue(BigInteger.ZERO);
		minDigitsField.setFormat(IntegerFormat.DEC);
		minDigitsField.setMaxValue(BigInteger.valueOf(32));
		minDigitsField.getComponent().setToolTipText(MIN_HEX_DIGITS_TOOLTIP);

		panel.add(minDigitsField.getComponent());

		label = new GDLabel(JUSTIFICATION_LABEL, SwingConstants.RIGHT);
		label.setToolTipText(RIGHT_JUSTIFY_TOOLTIP);
		panel.add(label);
		justificationCombobox = new(new string[] { "Left", "Right" });
		justificationCombobox.setToolTipText(RIGHT_JUSTIFY_TOOLTIP);
		panel.add(justificationCombobox);

		label = new GDLabel(UPPER_CASE_LABEL, SwingConstants.RIGHT);
		label.setToolTipText(UPPER_CASE_TOOLTIP);
		panel.add(label);
		upperCaseCheckbox = new GCheckBox();
		upperCaseCheckbox.setToolTipText(UPPER_CASE_TOOLTIP);
		panel.add(upperCaseCheckbox);

		showBlocknameCheckbox.addItemListener(evt => firePropertyChange());
		justificationCombobox.addItemListener(evt => firePropertyChange());
		upperCaseCheckbox.addItemListener(evt => firePropertyChange());

		padCheckBox.addItemListener(evt => {
			bool enabled = !padCheckBox.isSelected();
			minDigitsField.setEnabled(enabled);
			firePropertyChange();
		});
		minDigitsField.addChangeListener(evt => firePropertyChange());
		return panel;
	}

	/* @Override */
	public void setValue(object value) {
		if (!(value is AddressFieldOptionsWrappedOption)) {
			return;
		}

		addressFieldOptionsWrappedOption = (AddressFieldOptionsWrappedOption) value;
		setValuesFromOption(addressFieldOptionsWrappedOption);
		firePropertyChange();
	}

	private int getMinNumberOfDigits() {
		return minDigitsField.getIntValue();
	}

	private void setValuesFromOption(AddressFieldOptionsWrappedOption option) {
		if (option.showBlockName() != showBlocknameCheckbox.isSelected()) {
			showBlocknameCheckbox.setSelected(option.showBlockName());
		}
		bool rightJust = justificationCombobox.getSelectedItem().equals("Right");
		if (option.rightJustify() != rightJust) {
			justificationCombobox.setSelectedIndex(option.rightJustify() ? 1 : 0);
		}
		if (option.padWithZeros() != padCheckBox.isSelected()) {
			padCheckBox.setSelected(option.padWithZeros());
		}
		if (!Integer.toString(option.getMinimumHexDigits())
				.equals(
					minDigitsField.getText())) {
			minDigitsField.setValue(option.getMinimumHexDigits());
		}
		bool enabled = !padCheckBox.isSelected();
		minDigitsField.setEnabled(enabled);
		if (option.displayUpperCase() != upperCaseCheckbox.isSelected()) {
			upperCaseCheckbox.setSelected(option.displayUpperCase());
		}
	}

	private AddressFieldOptionsWrappedOption createOptionFromValues() {
		AddressFieldOptionsWrappedOption newOption = new AddressFieldOptionsWrappedOption();
		newOption.setPadWithZeros(padCheckBox.isSelected());
		newOption.setMinimumHexDigits(getMinNumberOfDigits());
		newOption.setShowBlockName(showBlocknameCheckbox.isSelected());
		newOption.setRightJustify(justificationCombobox.getSelectedItem().equals("Right"));
		newOption.setDisplayUpperCase(upperCaseCheckbox.isSelected());
		return newOption;
	}

	/* @Override */
	public string[] getOptionDescriptions() {
		return DESCRIPTIONS;
	}

	/* @Override */
	public string[] getOptionNames() {
		return NAMES;
	}

	/* @Override */
	public object getValue() {
		return createOptionFromValues();
	}

	/* @Override */
	public Component getCustomEditor() {
		return editorComponent;
	}

	/* @Override */
	public bool supportsCustomEditor() {
		return true;
	}
}
